            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class SegmentTree {
        int n;
        int[] sum;
        boolean[] cleared;

        SegmentTree(int n) {
            this.n = n;
            sum = new int[4 * n];
            cleared = new boolean[4 * n];
        }

        void clearRange(int ql, int qr) {
            clearRange(1, 0, n - 1, ql, qr);
        }

        private void clearRange(int node, int left, int right, int ql, int qr) {
            if (ql <= left && right <= qr) {
                sum[node] = 0;
                cleared[node] = true;
                return;
            }
            push(node);
            int mid = (left + right) >>> 1;
            if (ql <= mid) clearRange(node << 1, left, mid, ql, qr);
            if (qr > mid) clearRange(node << 1 | 1, mid + 1, right, ql, qr);
            sum[node] = sum[node << 1] + sum[node << 1 | 1];
        }

        void setPoint(int index) {
            setPoint(1, 0, n - 1, index);
        }

        private void setPoint(int node, int left, int right, int index) {
            if (left == right) {
                sum[node] = 1;
                cleared[node] = false;
                return;
            }
            push(node);
            int mid = (left + right) >>> 1;
            if (index <= mid) setPoint(node << 1, left, mid, index);
            else setPoint(node << 1 | 1, mid + 1, right, index);
            sum[node] = sum[node << 1] + sum[node << 1 | 1];
        }

