            push(node);
            int mid = (left + right) >>> 1;
            int result = 0;
            if (ql <= mid) result += rangeSum(node << 1, left, mid, ql, qr);
            if (qr > mid) result += rangeSum(node << 1 | 1, mid + 1, right, ql, qr);
