            int chainStart = stack[--stackSize];
            for (int v = chainStart; v != 0; v = heavy[v]) {
                head[v] = chainStart;
                position[v] = timer;
                nodeAtPosition[timer++] = v;

                for (int child = firstChild[v]; child != -1; child = nextSibling[child]) {
                    if (child != heavy[v]) stack[stackSize++] = child;
                }
            }
        }

        log = 1;
        while ((1 << log) <= n) log++;
        up = new int[log][n + 1];
        for (int i = 1; i <= n; i++) up[0][i] = parent[i];
        for (int bit = 1; bit < log; bit++) {
            for (int i = 1; i <= n; i++) {
                up[bit][i] = up[bit - 1][up[bit - 1][i]];
            }
        }

        SegmentTree segmentTree = new SegmentTree(n);
        int q = fs.nextInt();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++) {
            int type = fs.nextInt();
            int v = fs.nextInt();

            if (type == 1) {
                int k = fs.nextInt();
                output.append(answerQuery(v, k, segmentTree)).append('\n');
            } else {
                int left = position[v];
                int right = left + subtreeSize[v] - 1;
                segmentTree.clearRange(left, right);
                segmentTree.setPoint(position[v]);
            }
        }

        System.out.print(output);
    }
}
